// 拉取某几个阶段的全量检查单（分页拉全，避免漏掉跨页记录），返回已按 bizState 映射 status 的记录。
async function fetchInspectionRecords(kinds: InspectionType[], keyword?: string): Promise<FloodRecord[]> {
  const out: FloodRecord[] = []
  for (const kind of kinds) {
    let pageNum = 1
    const pageSize = 200
    let fetched = 0
    let total = Number.POSITIVE_INFINITY
    while (fetched < total) {
      const params = new URLSearchParams({ pageNum: String(pageNum), pageSize: String(pageSize), inspectionStage: STAGE[kind], subject: 'property' })
      if (keyword) params.set('keyWord', keyword)
      const page = await request<PageVo<InspectionRow>>(`/v2.0/safety/flood/inspection/page?${params.toString()}`, { raw: true })
      const rows = (page.rows ?? []).map(inspectionRowToRecord).filter(r => r.kind === kind)
      out.push(...rows)
      fetched += rows.length
      total = Number(page.total ?? 0)
      if (rows.length < pageSize) break
      pageNum++
    }
  }
  return out
}
